#include <bits/stdc++.h>
using namespace std;

const long long MOD_CONST = 998244353;

long long power(long long base, long long exp, long long mod) {
    long long res = 1LL;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % mod;
        }
        exp >>= 1;
        base = (base * base) % mod;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;

    long long total = N * M;
    __int128 totalPower = (__int128)total;
    __int128 rangeCount = (__int128)(R - L + 1);
    __int128 modBig = (__int128)MOD_CONST;

    if ((N * M) % 2 == 1) {
        __int128 answer = 1;
        __int128 base = rangeCount % MOD_CONST;
        long long total_pow = (long long)totalPower;
        // Modular exponentiation
        long long res = 1;
        long long b = base;
        long long e = total_pow;
        while (e > 0) {
            if (e & 1) {
                res = (res * b) % MOD_CONST;
            }
            e >>= 1;
            b = (b * b) % MOD_CONST;
        }
        answer = res;
        cout << (long long)((answer + MOD_CONST) % MOD_CONST) << "\n";
    } else {
        __int128 answer = 1;
        __int128 base = rangeCount % MOD_CONST;
        long long total_pow = (long long)totalPower;
        long long res = 1;
        long long b = base;
        long long e = total_pow;
        while (e > 0) {
            if (e & 1) {
                res = (res * b) % MOD_CONST;
            }
            e >>= 1;
            b = (b * b) % MOD_CONST;
        }
        answer = res;
        if ((R - L) % 2 == 0) {
            answer++;
        }
        long long invTwo = power(2, MOD_CONST - 2, MOD_CONST);
        answer = (answer * invTwo) % MOD_CONST;
        cout << (long long)answer << "\n";
    }
    return 0;
}

